import { DateTime } from "../src/luxon";

function refDate(y, m, d) {
  const dt = new Date(Date.UTC(2000, m - 1, d));
  dt.setUTCFullYear(y);
  return dt;
}
function refAddDays(y, m, d, n) {
  return new Date(refDate(y, m, d).getTime() + n * 86400000);
}
function dim(y, m) {
  const dt = new Date(Date.UTC(2000, m - 1, 1));
  dt.setUTCFullYear(y);
  dt.setUTCMonth(m);
  dt.setUTCDate(0);
  return dt.getUTCDate();
}
function refAddMonths(y, m, d, n) {
  let tm = m - 1 + n;
  const ty = y + Math.floor(tm / 12);
  tm = ((tm % 12) + 12) % 12;
  return [ty, tm + 1, Math.min(d, dim(ty, tm + 1))];
}

test("plus across the 100 barrier (days/months/years/weeks)", () => {
  let bad = 0;
  for (const y of [0, 1, 50, 96, 97, 98, 99]) {
    for (const m of [1, 2, 11, 12]) {
