          const ref = refAddDays(y, m, d, n);
          if (got.year !== ref.getUTCFullYear() || got.month !== ref.getUTCMonth() + 1 || got.day !== ref.getUTCDate()) {
            bad++; if (bad < 10) console.log(`DAYS ${iso}+${n} -> ${got.toISODate()} expected ${ref.toISOString().slice(0,10)}`);
          }
        }
        for (const n of [1, 2, 3, 11, 12, 13, 25, 61]) {
          const got = dt.plus({ months: n });
          const [ey, em, ed] = refAddMonths(y, m, d, n);
          if (got.year !== ey || got.month !== em || got.day !== ed) {
            bad++; if (bad < 10) console.log(`MONTHS ${iso}+${n} -> ${got.toISODate()} expected ${ey}-${em}-${ed}`);
          }
